import { problemResponse } from './problem-details'

// POST /api/gemma/read: Ctrl-O `?` mode's overview, generated by Gemma 4 E4B on Modal
// (quartz/scripts/latent/modal_gemma.py) and streamed back as newline-delimited JSON, the same
// protocol plt_serve.py speaks on localhost. The Worker is the only holder of the Modal proxy
// token; it bounds the request, rate limits it, and passes the stream through without buffering.
// Design and costs: docs/latent-modal.md.

export interface GemmaEnv {
  GEMMA_MODAL_URL?: string // https://<workspace>--garden-gemma-gemma-web.modal.run
  GEMMA_MODAL_KEY?: string // wrangler secret put GEMMA_MODAL_KEY
  GEMMA_MODAL_SECRET?: string // wrangler secret put GEMMA_MODAL_SECRET
  GEMMA_RATE_LIMITER?: RateLimit // per visitor
  GEMMA_GLOBAL_RATE_LIMITER?: RateLimit // all visitors: the burn-rate ceiling
}

export const GEMMA_READ_PATH = '/api/gemma/read'

const LIMITS = {
  query: 240,
  passages: 10,
  passageText: 2400,
  slug: 300,
  maxTokens: 200,
  readout: 4,
  steer: 8,
  mask: 10,
}

export interface ReadBody {
  query: string
  passages: { row: number; slug: string; text: string }[]
  think: boolean
  max_tokens: number
  readout?: number[]
  steer?: { layer: number; id: number; s: number }[]
  mask?: { row: number; bias: number }[]
}

const isInt = (v: unknown, lo: number, hi: number): v is number =>
  Number.isInteger(v) && (v as number) >= lo && (v as number) <= hi
const isNum = (v: unknown, lo: number, hi: number): v is number =>
  typeof v === 'number' && Number.isFinite(v) && v >= lo && v <= hi

/** The request Modal sees: only known fields, every one bounded. Returns a reason on refusal. */
export function boundReadBody(raw: unknown): ReadBody | string {
  if (!raw || typeof raw !== 'object') return 'body must be a JSON object'
  const body = raw as Record<string, unknown>
  const query = typeof body.query === 'string' ? body.query.trim().replace(/\s+/g, ' ') : ''
  if (!query) return 'query is required'
  if (query.length > LIMITS.query) return `query is longer than ${LIMITS.query} characters`
  if (!Array.isArray(body.passages) || body.passages.length === 0) return 'passages are required'
  const passages: ReadBody['passages'] = []
  for (const p of body.passages.slice(0, LIMITS.passages)) {
    const { row, slug, text } = (p ?? {}) as Record<string, unknown>
    if (!isInt(row, 0, 1e9) || typeof slug !== 'string' || typeof text !== 'string')
      return 'each passage is {row, slug, text}'
    passages.push({
      row,
      slug: slug.slice(0, LIMITS.slug),
      text: text.slice(0, LIMITS.passageText),
    })
  }
  const out: ReadBody = {
    query,
    passages,
    think: body.think === true,
    max_tokens: isInt(body.max_tokens, 1, LIMITS.maxTokens) ? body.max_tokens : 120,
  }
  if (Array.isArray(body.readout))
    out.readout = body.readout.filter(l => isInt(l, 0, 41)).slice(0, LIMITS.readout)
  if (Array.isArray(body.steer)) {
    out.steer = []
    for (const s of body.steer.slice(0, LIMITS.steer)) {
      const { layer, id, s: k } = (s ?? {}) as Record<string, unknown>
      if (!isInt(layer, 0, 41) || !isInt(id, 0, 8191) || !isNum(k, -20, 20))
        return 'each steer is {layer 0-41, id 0-8191, s -20..20}'
      out.steer.push({ layer, id, s: k })
    }
  }
  if (Array.isArray(body.mask)) {
    out.mask = []
    for (const m of body.mask.slice(0, LIMITS.mask)) {
      const { row, bias } = (m ?? {}) as Record<string, unknown>
      if (!isInt(row, 0, 1e9) || !isNum(bias, -1e30, 10)) return 'each mask is {row, bias}'
      out.mask.push({ row, bias })
    }
  }
  return out
}

function refuse(
  request: Request,
  status: number,
  code: string,
  detail: string,
  headers?: Record<string, string>,
) {
  return problemResponse(request, {
    status,
    title: status === 429 ? 'Overview rate limit exceeded' : 'Overview unavailable',
    detail,
    code,
    headers,
  })
}

export async function handleGemmaRead(request: Request, env: GemmaEnv): Promise<Response> {
  // a cheap probe, so the client can skip loading passages when nothing would answer
  if (request.method === 'GET' || request.method === 'HEAD')
    return new Response(null, {
      status: env.GEMMA_MODAL_URL && env.GEMMA_MODAL_KEY && env.GEMMA_MODAL_SECRET ? 204 : 503,
      headers: { 'Cache-Control': 'no-store' },
    })
  if (request.method !== 'POST')
    return refuse(request, 405, 'method_not_allowed', 'POST a {query, passages} body.', {
      Allow: 'GET, HEAD, POST',
    })
  // same-origin only: the page's own fetch sends Origin; another site's script cannot spend this
  const origin = request.headers.get('Origin')
  if (origin !== new URL(request.url).origin)
    return refuse(request, 403, 'cross_origin', 'Overviews are only served to this site.')
  if (!env.GEMMA_MODAL_URL || !env.GEMMA_MODAL_KEY || !env.GEMMA_MODAL_SECRET)
    return refuse(request, 503, 'not_deployed', 'The overview model is not deployed.')

  const visitor = request.headers.get('CF-Connecting-IP') ?? 'local'
  for (const [limiter, key] of [
    [env.GEMMA_RATE_LIMITER, visitor],
    [env.GEMMA_GLOBAL_RATE_LIMITER, 'all'],
  ] as const) {
    if (limiter && !(await limiter.limit({ key })).success)
      return refuse(request, 429, 'rate_limited', 'Too many overviews this minute.', {
        'Retry-After': '60',
      })
  }

  let raw: unknown
  try {
    raw = await request.json()
  } catch {
    return refuse(request, 400, 'bad_json', 'The body is not JSON.')
  }
  const body = boundReadBody(raw)
  if (typeof body === 'string') return refuse(request, 400, 'bad_request', body)

  let upstream: Response
  try {
    upstream = await fetch(`${env.GEMMA_MODAL_URL.replace(/\/$/, '')}/read`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Modal-Key': env.GEMMA_MODAL_KEY,
        'Modal-Secret': env.GEMMA_MODAL_SECRET,
      },
      body: JSON.stringify(body),
      signal: request.signal,
    })
  } catch {
    return refuse(request, 502, 'upstream_unreachable', 'The overview model did not answer.')
  }
  if (!upstream.ok || !upstream.body)
    return refuse(request, 502, 'upstream_error', `The overview model answered ${upstream.status}.`)
  return new Response(upstream.body, {
    status: 200,
    headers: {
      'Content-Type': 'application/x-ndjson; charset=utf-8',
      'Cache-Control': 'no-store',
      'X-Content-Type-Options': 'nosniff',
    },
  })
}
